const HTML = "<div style=\"display:flex;align-items:flex-start;min-height:100vh\">\n\n<nav style=\"flex:none;width:272px;position:sticky;top:0;height:100vh;overflow-y:auto;padding:26px 14px 28px;border-right:1px solid rgba(233,233,237,.09)\">\n<div style=\"padding:0 10px 22px\">\n<a href=\"/\" style=\"display:block;font:500 14.5px/1 Inter,system-ui,sans-serif;letter-spacing:-.01em;color:#e9e9ed;text-decoration:none\">brugada.net</a>\n<div style=\"margin-top:6px;font:400 10.5px/1.4 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.42)\">SCN5A p.Arg104Gln</div>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:22px\">\n<div style=\"display:flex;flex-direction:column;gap:3px\">\n<div style=\"padding:0 10px 8px;font:500 9.5px/1 ui-monospace,Menlo,monospace;letter-spacing:.14em;text-transform:uppercase;color:rgba(233,233,237,.34)\">Start here</div>\n<a href=\"/new-here\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h1\"><span style=\"display:none\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">New here</span></a>\n<a href=\"/for-carriers\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h2\"><span style=\"display:none\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">For carriers</span></a>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:3px\">\n<div style=\"padding:0 10px 8px;font:500 9.5px/1 ui-monospace,Menlo,monospace;letter-spacing:.14em;text-transform:uppercase;color:rgba(233,233,237,.34)\">The evidence</div>\n<a href=\"/science\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h3\"><span style=\"display:none\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">The science</span></a>\n<a href=\"/routes\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h4\"><span style=\"position:absolute;inset:0;z-index:0;border-radius:0 5px 5px 0;background:rgba(233,233,237,.07);box-shadow:inset 2px 0 0 #9184d9\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">Routes</span></a>\n<a href=\"/open\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h5\"><span style=\"display:none\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">What is open</span></a>\n<a href=\"/experiments\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h6\"><span style=\"display:none\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">Experiments</span></a>\n<a href=\"/limitations\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h7\"><span style=\"display:none\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">Limitations</span></a>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:3px\">\n<div style=\"padding:0 10px 8px;font:500 9.5px/1 ui-monospace,Menlo,monospace;letter-spacing:.14em;text-transform:uppercase;color:rgba(233,233,237,.34)\">The record</div>\n<a href=\"/papers\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h8\"><span style=\"display:none\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">Papers</span></a>\n<a href=\"/data\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h9\"><span style=\"display:none\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">Data</span></a>\n<a href=\"/census\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h10\"><span style=\"display:none\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">Census</span></a>\n<a href=\"/history\" style=\"position:relative;display:block;padding:6px 10px;border-radius:0 5px 5px 0;text-decoration:none\" class=\"h11\"><span style=\"display:none\"></span><span style=\"position:relative;z-index:1;font:400 13.5px/1.35 Inter,system-ui,sans-serif;color:rgba(233,233,237,.78)\">History</span></a>\n</div>\n</div>\n<div style=\"margin:26px 10px 0;padding-top:16px;border-top:1px solid rgba(233,233,237,.09);font:400 11px/1.5 Inter,system-ui,sans-serif;color:rgba(233,233,237,.4)\">Not a physician. Nothing here is medical advice.</div>\n</nav>\n\n<div style=\"flex:1;min-width:0\">\n<div style=\"display:flex;align-items:center;justify-content:space-between;gap:20px;padding:14px 56px;border-bottom:1px solid rgba(233,233,237,.09)\"><span style=\"font:400 11px/1 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.42)\">a public research record</span><span style=\"font:400 11px/1 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.42)\">last updated 13 August 2026</span></div>\n\n\n<main style=\"padding:52px 56px 40px;max-width:900px\">\n<div style=\"font:500 10px/1 ui-monospace,Menlo,monospace;letter-spacing:.14em;text-transform:uppercase;color:rgba(233,233,237,.42)\">Therapeutic routes</div>\n<h1 style=\"margin:14px 0 0;font:500 36px/1.16 Inter,system-ui,sans-serif;letter-spacing:-.022em;color:#e9e9ed;text-wrap:pretty\">Thirteen lines, eleven of them therapeutic, including the three that are closed.</h1>\n<p style=\"margin:16px 0 0;max-width:58ch;font:400 17px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.78)\">The dead ones are listed with the measurement that closed them. A page showing only the live options would be advocacy rather than a record. A longer list is not better news: most of these lines are closed, conditional, or waiting on the same measurement as everything else. Current care is listed last, unranked, so the comparison sits on the page rather than being assumed.</p>\n\n<div style=\"margin-top:30px;max-width:74ch;padding:16px 18px;border-left:2px solid #9184d9;background:rgba(233,233,237,.03)\">\n<p style=\"margin:0;font:500 15px/1.55 Inter,system-ui,sans-serif;color:#e9e9ed\">None of this is a treatment, or close to one.</p>\n<p style=\"margin:9px 0 0;font:400 14.5px/1.6 Inter,system-ui,sans-serif;color:rgba(233,233,237,.72)\">The strongest statement available is that one route now has a designed guide, a genome wide safety scan, and a costed validation experiment. That is a long way from a therapy, and saying so is what makes the rest believable.</p>\n</div>\n\n<div style=\"margin-top:34px;max-width:74ch\">\n<div style=\"font:500 10px/1 ui-monospace,Menlo,monospace;letter-spacing:.14em;text-transform:uppercase;color:rgba(233,233,237,.42)\">Eleven routes, ranked by strength of case</div>\n<div style=\"display:flex;gap:3px;margin-top:16px\">\n<div style=\"flex:1;height:8px;border-radius:2px;background:#796cbf\"></div>\n<div style=\"flex:5;height:8px;border-radius:2px;background:rgba(233,233,237,.28)\"></div>\n<div style=\"flex:2;height:8px;border-radius:2px;background:rgba(233,233,237,.14)\"></div>\n<div style=\"flex:3;height:8px;border-radius:2px;background:repeating-linear-gradient(135deg,rgba(233,233,237,.16) 0 3px,transparent 3px 6px)\"></div>\n</div>\n<div style=\"display:flex;gap:14px;flex-wrap:wrap;margin-top:9px;font:400 10.5px/1 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.45)\"><span>1 leading</span><span>5 conditional</span><span>2 weak</span><span>3 dead</span></div>\n</div>\n\n<div style=\"margin-top:34px;max-width:74ch;display:flex;flex-direction:column;gap:30px\">\n<div>\n<h2 style=\"margin:0 0 12px;font:600 20px/1.24 'Source Serif 4',Georgia,serif;color:#e9e9ed\">Leading, and still unvalidated</h2>\n<div style=\"padding-left:14px;border-left:2px solid #9184d9\">\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">1</span><div><div style=\"font:500 16px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">DNA base editing</div><p style=\"margin:6px 0 0;font:400 15px/1.62 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.75)\">A designed guide, a genome wide safety scan, and a costed validation experiment. What blocks it is that nobody has run it, and that needs a laboratory.</p></div></div>\n</div>\n</div>\n<div>\n<h2 style=\"margin:0 0 12px;font:600 20px/1.24 'Source Serif 4',Georgia,serif;color:#e9e9ed\">Conditional, meaning something specific is missing</h2>\n<div style=\"padding-left:14px;border-left:1px solid rgba(233,233,237,.14);display:flex;flex-direction:column;gap:14px\">\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">2</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">Prime editing</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">The better designed option at this site and the worse delivered one: published correction of 11 percent in heart against base editing's 99.2 percent in a dish. Base editing has the efficiency, prime editing has the specificity, and neither has been tested in a human heart cell.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">4</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">Chaperone and interacting partner upregulation</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">Found late, in this project's own literature collection, by a pass that finally asked whether each paper described a route rather than a protocol. The deciding measurement sits in a paywalled paper with no copy in any repository, and six attempts to retrieve it failed, so the test was never run rather than passed.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">9</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">Gene replacement</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">The gene is too large for the standard delivery vehicle.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">10</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">A different, smaller sodium channel</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">The only entry that does not wait on the mechanism question, because it does not interact with the human channel at all. It waits on an immunology question instead. A candidate, and not promising.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">11</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">Raising output from the healthy copy by other means</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">Separated out on 6 August 2026, when rank 6's heading was found to be closing this level by wording rather than by evidence. Unassessed, which is not the same as promising.</p></div></div>\n</div>\n</div>\n<div>\n<h2 style=\"margin:0 0 12px;font:600 20px/1.24 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.75)\">Weak</h2>\n<div style=\"padding-left:14px;border-left:1px solid rgba(233,233,237,.1);display:flex;flex-direction:column;gap:14px\">\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.3)\">3</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:rgba(233,233,237,.85)\">RNA editing</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.66)\">Every design tested either changed neighbouring letters it should not have, or bound in too many other places. Separately, no molecule of this class has been shown to reach a human heart muscle cell at all.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.3)\">7</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:rgba(233,233,237,.85)\">Silencing the broken copy</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.66)\">Telling the broken copy apart from the working one is the hardest discrimination class there is: a single letter of difference.</p></div></div>\n</div>\n</div>\n<div>\n<h2 style=\"margin:0 0 4px;font:600 20px/1.24 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.68)\">Dead, with the measurement that closed it</h2>\n<p style=\"margin:0 0 12px;font:400 13px/1.55 Inter,system-ui,sans-serif;color:rgba(233,233,237,.45)\">A closed route is a result. It is one fewer thing for the next person to try.</p>\n<div style=\"padding-left:14px;border-left:1px solid rgba(233,233,237,.08);display:flex;flex-direction:column;gap:14px\">\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.26)\">5</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:rgba(233,233,237,.7)\">Interaction drug</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.6)\">No target, no assay, and a ceiling it cannot pass. It had been on this page since the site was built while the project's own inventory had quietly stopped listing it. It is now restored to that inventory as closed. Being restored is not the same as being revived.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.26)\">6</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:rgba(233,233,237,.7)\">Redirecting the healthy copy's discarded messages</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.6)\">The most attractive route on this list, because it did not depend on resolving the mechanism first. It needed a reserve of discarded message to redirect, and the analysis said in advance the route would die if that reserve turned out to be a few percent. It measured 0.0045 percent across 827 hearts.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.26)\">8</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:rgba(233,233,237,.7)\">Folding corrector</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.6)\">Premise refuted by this project's own paper 1. The predictor it rested on caught one of four variants already known to break this channel.</p></div></div>\n</div>\n</div>\n<div style=\"padding-top:20px;border-top:1px solid rgba(233,233,237,.09)\">\n<div style=\"font:500 9.5px/1 ui-monospace,Menlo,monospace;letter-spacing:.12em;text-transform:uppercase;color:rgba(233,233,237,.38)\">Unranked, for comparison</div>\n<p style=\"margin:10px 0 0;font:400 15px/1.62 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.75)\">Current care: an implanted defibrillator and existing drugs. For most people carrying a variant like this one it does not apply, because guideline indications for a device require a prior cardiac arrest, a documented sustained arrhythmia, or fainting from an arrhythmia together with a spontaneous type 1 pattern. A device also does not treat the disease: it stops an arrhythmia after it has already started, and does nothing to the sodium current, the protein or the gene. For most of the people a therapy would be developed for, the comparator is no treatment at all.</p>\n</div>\n</div>\n\n<h2 style=\"margin:44px 0 0;max-width:74ch;font:500 24px/1.26 Inter,system-ui,sans-serif;letter-spacing:-.016em;color:#e9e9ed\">What changed in the second week of August</h2>\n<p style=\"margin:14px 0 0;max-width:70ch;font:400 16px/1.66 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.8)\">Four of these lines moved, one gained a candidate that had been sitting unread in this project's own literature collection, and one number that had been quoted with confidence was withdrawn rather than corrected. None of it makes any route live. Most of it is the ordinary work of finding that a published thing was read too quickly, including by me.</p>\n<div style=\"padding-left:14px;border-left:1px solid rgba(233,233,237,.14);display:flex;flex-direction:column;gap:14px;margin-top:16px\">\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">01</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">A number was withdrawn, and the correction runs in the route's favour</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">This project had put the only drug that exists for the interaction route at 85 percent of the way to abolishing the interference, and concluded it fell short. That figure came from a summary of a paper rather than from the paper. The paper prints the quantity in a table: the drug delivered two and a half times the current, not one and a half, which is more than complete abolition. But a fraction that exceeds one falsifies the model that defines it, and the paper's own statistics mark no current comparison as significant. So the claim is withdrawn rather than replaced with a new number. The route stays closed, for want of a target, which is not what the number was about.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">02</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">A magnitude recorded as unreadable is readable, and it clears the bar</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">One route had a deliverable small molecule with a current measurement whose size this project had recorded as impossible to read off the figure. Digitised from the published article: the treated cells recover to 87 percent of control, a rescue of about 1.8 fold against a requirement of 1.46. So the objection that the deliverable agent was never measured on current is now doubly wrong. The route does not move, because magnitude was never what blocked it. Neither of the published patient cell lines carries this variant, and that is the objection that binds.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">03</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">The gene replacement route has a failure mode nobody has looked for</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">The published construct splits the gene across two vectors joined by a short piece of spacer sequence. That spacer is 133 bases, which is not divisible by three, so a copy that fails to join correctly shifts the reading frame and produces a half channel of about 121 kilodaltons. In the genome such fragments are destroyed before they are built; in a vector that safeguard is absent. The fragment keeps the part that lets channels associate and loses the part that conducts, which is the shape of a poison. The published test could not have seen it: the membrane was cut at 130 kilodaltons to run a loading control, and the fragment falls below the cut.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">04</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">A candidate with the smallest cargo of anything here, and it is human</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">A 2016 paper, retrieved by this project's own search and never read because it sits behind a paywall, reports that the first 132 amino acids of this channel, delivered alone as a free peptide, raise the amount of channel at the cell surface. That is about 400 bases against the 6,048 of the whole gene, and it is a fragment of the patient's own protein rather than a bacterial one. It also raises a second, potassium current, which is the same objection this project used against another route and must be applied with the same force. Recorded as a candidate, unnumbered, and not promising.</p></div></div>\n</div>\n<div style=\"padding-left:14px;border-left:1px solid rgba(233,233,237,.14);display:flex;flex-direction:column;gap:14px;margin-top:16px\">\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">05</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">A second heart cell model declines to reproduce the published result</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">The surrogate channel route rests on a published simulation in which adding a small bacterial channel restores a Brugada heart cell to normal. Re-running that claim in a second, independently developed model of a heart cell gives no such restoration: the part of the beat that the published work says is rescued is left untouched in every arm, including the healthy control. Two models built by different groups from different data both decline to host the published effect. That is a fact about the specification rather than about either model, and it is a negative result against a route this project had already recorded as a candidate rather than a plan.</p></div></div>\n<div style=\"display:flex;gap:12px;align-items:baseline\"><span style=\"font:400 11px/1.6 ui-monospace,Menlo,monospace;color:rgba(233,233,237,.35)\">06</span><div><div style=\"font:500 15.5px/1.45 Inter,system-ui,sans-serif;color:#e9e9ed\">The interaction route now has the target list its closure said did not exist</div><p style=\"margin:5px 0 0;font:400 14.5px/1.6 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.72)\">That route is closed for want of anything to aim a drug at. A 2023 study that has been in this project's literature collection the whole time lists sixty proteins that stick to this channel in heart tissue, two of them with the current measurement to show they matter, and it was found by opening a supplementary file rather than by reading the paper. The channel also appears in its own list, ranked third, which is independent biochemical support for the pairing the whole route depends on. It does not reopen the route. Sticking to something is not the same as gating with it, which is the correction a researcher made to this project in the same week, and the route stays closed.</p></div></div>\n</div>\n\n<p style=\"margin:14px 0 0;max-width:70ch;font:400 16px/1.66 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.8)\">One more, on the chaperone route. A reply from the laboratory that developed it establishes that the therapy works by recruiting more of the healthy copy rather than by repairing the broken one. Under that mechanism the arithmetic has no harmful branch at all: adding healthy channel raises the total and dilutes the broken fraction at the same time, so there is no threshold to clear. That is a better shape than the model this project had been using. It does not make the route live, and it sharpens rather than removes the concern about variants that interfere, which is the case the reply was not asked about.</p>\n<p style=\"margin:14px 0 0;max-width:70ch;font:400 16px/1.66 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.8)\">The usual answer is that a condition is too rare to attract attention. That is not the reason here, and the real one is more interesting because it will not change. The mouse study that makes gene editing look ready for the heart corrected a different variant in this same gene, one that causes the opposite kind of change, and its effect shows up as a measurable interval on a mouse electrocardiogram. A researcher can inject, record, and watch the number move.</p>\n<p style=\"margin:12px 0 0;max-width:70ch;font:400 16px/1.66 'Source Serif 4',Georgia,serif;color:rgba(233,233,237,.8)\">Brugada syndrome has no equivalent readout. Its signature depends on a difference in electrical recovery across the thickness of the right ventricular wall, and mouse hearts do not reproduce that gradient. So an editing study here can measure current in isolated cells and show the letter was corrected, but it cannot point at an animal and say the disease went away. That is the difference between one paper and five years of work, and no amount of funding removes it.</p>\n\n<div style=\"display:flex;flex-wrap:wrap;gap:10px;margin-top:34px\">\n<a href=\"/experiments\" style=\"padding:9px 14px;border:1px solid rgba(233,233,237,.14);border-radius:8px;font:400 13px/1.2 Inter,system-ui,sans-serif;color:rgba(233,233,237,.85);text-decoration:none\" class=\"h12\">The two costed protocols</a>\n<a href=\"/papers\" style=\"padding:9px 14px;border:1px solid rgba(233,233,237,.14);border-radius:8px;font:400 13px/1.2 Inter,system-ui,sans-serif;color:rgba(233,233,237,.85);text-decoration:none\" class=\"h13\">The papers behind each verdict</a>\n</div>\n</main>\n\n\n<footer style=\"padding:34px 56px 44px;max-width:900px;border-top:1px solid rgba(233,233,237,.09);margin-top:40px\">\n<p style=\"margin:0;max-width:70ch;font:400 13.5px/1.65 Inter,system-ui,sans-serif;color:rgba(233,233,237,.62)\">Written by Ethan Bradley, who carries SCN5A p.Arg104Gln. Not a physician. The work here is computational and the reasoning is public so that anyone can check it. <a href=\"https://orcid.org/0009-0008-8925-7975\">ORCID 0009-0008-8925-7975</a></p>\n<div style=\"height:1px;margin:18px 0;max-width:70ch;background:linear-gradient(to right,transparent,rgba(233,233,237,.16) 48px,rgba(233,233,237,.16) calc(100% - 48px),transparent)\"></div>\n<p style=\"margin:0;max-width:70ch;font:400 13.5px/1.65 Inter,system-ui,sans-serif;color:rgba(233,233,237,.62)\"><b style=\"font-weight:500;color:#e9e9ed\">This site cannot tell you your risk.</b> It explains what has been measured about one variant. Risk assessment belongs to an electrophysiologist who has your whole picture. Nothing here is medical advice, and no result on this site should change anyone's treatment.</p>\n<p style=\"margin:10px 0 0;max-width:70ch;font:400 13.5px/1.65 Inter,system-ui,sans-serif;color:rgba(233,233,237,.5)\">None of this work has been peer reviewed. Preprints are posted publicly before review by design, so that the reasoning and the errors are both visible.</p>\n<div style=\"height:1px;margin:18px 0;max-width:70ch;background:linear-gradient(to right,transparent,rgba(233,233,237,.16) 48px,rgba(233,233,237,.16) calc(100% - 48px),transparent)\"></div>\n<p style=\"margin:0;max-width:70ch;font:400 13.5px/1.65 Inter,system-ui,sans-serif;color:rgba(233,233,237,.62)\"><b style=\"font-weight:500;color:#e9e9ed\">Contact.</b> <a href=\"mailto:ethan@brugada.net\">ethan@brugada.net</a>. If you could put brugada.net to better use than I am, whether you are a patient group, a clinician or a research team, say so and I will hand it over. The papers and data stay published under my name regardless.</p>\n</footer>\n\n</div>\n</div>";

export default function Page() {
  return <div dangerouslySetInnerHTML={{ __html: HTML }} />;
}
